contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint setupValue, uint sentValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (setupValue) + (sentValue)); require(setupValue <= 1000000000000000000000000000000); require(sentValue <= 1000000000000000000000000000000);
        require(setupValue <= 12);
        require(sentValue <= 12);
        require(address(this).balance >= setupValue + sentValue);

        c.play{value: setupValue}(); if (__ESBMC_reverted()) return;

        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.play{value: sentValue}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;

        assert(reverted ? potAfter == potBefore : (potAfter == potBefore + sentValue || potAfter == 0));
    }

    receive() external payable {}
}

