pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 setupValue, uint256 sentValue) internal {
        setupValue = bound(setupValue, 0, 1000000000000000000000000000000);
        sentValue = bound(sentValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        setupValue = bound(setupValue, 0, 12);
        sentValue = bound(sentValue, 0, 12);
        vm.assume(address(this).balance >= setupValue + sentValue);
        try c.play{value: setupValue}() {} catch { return; }
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        bool reverted;
        try c.play{value: sentValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        assertTrue(reverted ? potAfter == potBefore : (potAfter == potBefore + sentValue || potAfter == 0));
    }

    function testFuzz_run(uint256 setupValue, uint256 sentValue) public {
        _run(setupValue, sentValue);
    }

    receive() external payable {}
}
